require('dotenv').config();          // Loads .env on dev

const express    = require('express');
const helmet     = require('helmet');
const cors       = require('cors');
const rateLimit  = require('express-rate-limit');
const { query, validationResult } = require('express-validator');

const app = express();

/* ---------- SECURITY MIDDLEWARE ---------- */
app.use(helmet());                 // Sets strict HTTP security headers
app.use(cors({                     // Whitelist your actual frontend domain
  origin: 'https://myfrontend.com',
  optionsSuccessStatus: 200,
}));

app.use(express.json({ limit: '10mb' }));  // Reject huge payloads

/* ---------- RATE LIMIT ---------- */
app.use(
  rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 200,
    standardHeaders: true,
    legacyHeaders: false,
  })
);

/* ---------- ROUTES ---------- */
app.get(
  '/health',
  query('tz').optional().isString().trim().escape(),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  }
);

app.get('/users', (req, res, next) => {
  // Example of minimal data; consider auth in real code
