// app.js
// A toy Express application demonstrating best practices
// for error handling, request validation and security.

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { check, validationResult } = require('express-validator');

const app = express();

// ------------------------------------------------------------------
// 1️⃣  Security middleware
// ------------------------------------------------------------------
// Remove the `X-Powered-By` header (other headers added by helmet).  
app.disable('x-powered-by');
// Helmet sets a number of secure headers.
app.use(helmet());
// Simple CORS policy – only allow requests from the same domain in dev.
app.use(cors({ origin: process.env.CORS_ORIGIN || '*', credentials: true }));
// Rate‑limit all requests to avoid abuse.
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 min
  max: 1000,                // limit each IP to 1000 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Parse JSON bodies – if you later expose POST/PUT routes you’ll need this.
app.use(express.json());

// ------------------------------------------------------------------
// 2️⃣  Utility – centralized error handler
// ------------------------------------------------------------------
// Convert a non‑Error throw into an Error + send back a sanitized
// response.  All route handlers should call `next(err)` when something
// goes wrong.
// ------------------------------------------------------------------
// Helper to trigger error handling from inside an async route.
const asyncWrapper = fn => {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
};

// ------------------------------------------------------------------
// 3️⃣  Routes
// ------------------------------------------------------------------
app.get(
  '/health',
  asyncWrapper(async (req, res) => {
    // Small simulation of something that might fail
    if (process.env.MAY_FAIL === 'true') {
      throw new Error('Simulated error while health check');
    }
    res.status(200).json({ status: 'ok', timestamp: new Date().toISOString() });
  })
);

app.get(
  '/users',
  // Example of query‑param validation – future extensible.
  [
    check('limit', 'limit must be a positive integer').optional().isInt({ gt: 0 }),
    check('offset', 'offset must be a non‑negative integer').optional().isInt({ min: 0 }),
  ],
  asyncWrapper(async (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // In a real app this would come from a database.
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    const limit = parseInt(req.query.limit, 10) || users.length;
    const offset = parseInt(req.query.offset, 10) || 0;
    res.json(users.slice(offset, offset + limit));
  })
);

// ------------------------------------------------------------------
// 4️⃣  Global error handler – must come *after* all routes
// ------------------------------------------------------------------
app.use((err, req, res, next) => {
  // Log the stack internally – you might forward this to a log service.
  console.error(err.stack);

  // Only expose in dev; in prod keep a generic message.
  const message = process.env.NODE_ENV === 'development' ? err.message : 'Internal Server Error';

  res.status(500).json({ error: message });
});

// ------------------------------------------------------------------
// 5️⃣  Start the server – pull the port from ENV to support Docker, etc.
// ------------------------------------------------------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

