// app.js
// ---------------------------------------------------------------------------
// A toy Express application demonstrating best practices for
// error handling, request validation and security.
// ---------------------------------------------------------------------------

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { check, validationResult } = require('express-validator');

const app = express();

/* ------------------------------------------------------------------
   1️⃣  Security middleware
   ------------------------------------------------------------------ */
// Remove the 'X-Powered-By' header – makes it harder for attackers
// to guess the app tech stack.
app.disable('x-powered-by');

// Helmet sets a bunch of secure HTTP headers.
app.use(helmet());

// Simple CORS policy – change process.env.CORS_ORIGIN in prod.
app.use(cors({ origin: process.env.CORS_ORIGIN || '*', credentials: true }));

// Rate‑limit all requests to guard against brute‑force / DoS.
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 min
  max: 1000,                // each IP – 1000 req per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Parse JSON bodies (needed for any future POST/PUT routes).
app.use(express.json());

/* ------------------------------------------------------------------
   2️⃣  Utility – centralized error handler
   ------------------------------------------------------------------ */
// Helps keep async route handlers clean – any thrown error automatically
// bubbles to the global error middleware.
const asyncWrapper = fn => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

/* ------------------------------------------------------------------
   3️⃣  Routes
   ------------------------------------------------------------------ */
app.get(
  '/health',
  asyncWrapper(async (req, res) => {
    // Simulate a possible failure – just for demo.
    if (process.env.MAY_FAIL === 'true') {
      throw new Error('Simulated error while health check');
    }
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString()
    });
  })
);

app.get(
  '/users',
  // Basic query‑param validation – improves security & reliability.
  [
    check('limit', 'limit must be a positive integer')
      .optional()
      .isInt({ gt: 0 }),
    check('offset', 'offset must be a non‑negative integer')
      .optional()
      .isInt({ min: 0 })
  ],
  asyncWrapper(async (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      // Bad request – do not expose back‑end logic.
      return res.status(400).json({ errors: errors.array() });
    }

    // Demo data – would normally come from a database.
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ];

    const limit = parseInt(req.query.limit, 10) || users.length;
    const offset = parseInt(req.query.offset, 10) || 0;

    res.json(users.slice(offset, offset + limit));
  })
);

/* ------------------------------------------------------------------
   4️⃣  Global error handler – *after* all routes
   ------------------------------------------------------------------ */
app.use((err, req, res, next) => {
  // Log error details internally.
  console.error(err.stack);

  // Only expose the message in development; otherwise a generic string.
  const message = process.env.NODE_ENV === 'development' ? err.message : 'Internal Server Error';

  res.status(500).json({ error: message });
});

/* ------------------------------------------------------------------
   5️⃣  Start the server – pull port from env or default to 3000
   ------------------------------------------------------------------ */
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

