## 1. `test-env-connectivity.js`

```js
#!/usr/bin/env node
/**
 * test-env-connectivity.js
 *
 * This script loads the .env.test file and attempts a lightweight
 * operation against each of the external services that the app
 * might eventually call.  Use it as part of a CI pipeline or
 * an ad‑hoc check before a release.
 */

require('dotenv').config({ path: '.env.test' });

const { Client } = require('pg');
const AWS = require('aws-sdk');
const Anthropic = require('@anthropic-ai/sdk');
const Stripe = require('stripe');
const { Logfire } = require('@logfire/node');

// ─────────────────────────────────────────────────────────────
// Helper to colour console output
// ─────────────────────────────────────────────────────────────
const colour = (text, green = true) =>
  `%c${green ? '✅' : '❌'} ${text}`;

// ─────────────────────────────────────────────────────────────
// 1️⃣  PostgreSQL (DATABASE_URL)
// ─────────────────────────────────────────────────────────────
const testDb = async () => {
  const client = new Client({ connectionString: process.env.DATABASE_URL });
  try {
    await client.connect();
    await client.query('SELECT 1');
    console.info(colour('Database connectivity OK', true));
  } catch (err) {
    console.error(
      colour('Database connectivity failed', false),
      err.message,
    );
  } finally {
    await client.end();
  }
};

// ─────────────────────────────────────────────────────────────
// 2️⃣  AWS – list S3 buckets
// ─────────────────────────────────────────────────────────────
const testAws = async () => {
  const s3 = new AWS.S3();
  try {
    const data = await s3.listBuckets().promise();
    console.info(
      colour(`AWS S3 listBuckets succeeded (${data.Buckets.length})`, true),
    );
  } catch (err) {
    console.error(
      colour('AWS S3 listBuckets failed', false),
      err.message,
    );
  }
};

// ─────────────────────────────────────────────────────────────
// 3️⃣  Anthropic – create a tiny message
// ─────────────────────────────────────────────────────────────
const testAnthropic = async () => {
  const client = new Anthropic({
    client: new Anthropic.Http({ baseURL: 'https://api.anthropic.com' }),
    apiKey: process.env.ANTHROPIC_API_KEY,
  });

  try {
    const res = await client.messages.create({
      model: 'claude-3-5-sonnet-20240620',
      max_tokens: 10,
      messages: [{ role: 'user', content: 'Hello' }],
    });
    console.info(colour(`Anthropic API OK – ${res.status}`, true));
  } catch (err) {
    console.error(
      colour('Anthropic API error', false),
      err.message,
    );
  }
};

// ─────────────────────────────────────────────────────────────
// 4️⃣  Stripe – list products (requires a valid secret key)
// ─────────────────────────────────────────────────────────────
const testStripe = async () => {
  const stripe = Stripe(process.env.STRIPE_SECRET_KEY, {
    apiVersion: '2023-10-16',
  });

  try {
    const list = await stripe.products.list({ limit: 1 });
    console.info(
      colour(`Stripe listProducts succeeded (${list.data.length})`, true),
    );
  } catch (err) {
    console.error(
      colour('Stripe request failed', false),
      err.message,
    );
  }
};

// ─────────────────────────────────────────────────────────────
// 5️⃣  Logfire – send a lightweight log message
// ─────────────────────────────────────────────────────────────
const testLogfire = async () => {
  const logfire = new Logfire({
    token: process.env.LOGFIRE_TOKEN,
    destination: 'console', // nearest possible replace for a real service
  });

  try {
    await logfire.info('🧪 Test message from env‑validation script');
    console.info(colour('Logfire event sent', true));
  } catch (err) {
    console.error(
      colour('Logfire submit failed', false),
      err.message,
    );
  }
};

// ─────────────────────────────────────────────────────────────
// Execute all tests in parallel
// ─────────────────────────────────────────────────────────────
(async () => {
  console.log('=== Environment Connectivity Test ===');
  await Promise.all([
    testDb(),
    testAws(),
    testAnthropic(),
    testStripe(),
    testLogfire(),
  ]);
  console.log('=== Done ===');
})();
```

