// scripts/test-credentials.js

// ------------------------------------------------------------
// Small helper to verify that the credentials defined in
// .env.test are still usable.  It tries three things:
//  1. Connect to the PostgreSQL database via the URL.
//  2. Call the Anthropic API to list models.
//  3. Retrieve the linked Stripe account.
//
// This script uses official client libraries where possible
// (pg, stripe) and native fetch for the Anthropic HTTP call.
// ------------------------------------------------------------

require('dotenv').config({ path: '.env.test' });
const { Client } = require('pg');
const stripeLib = require('stripe');

const fetch = (...args) => import('node-fetch').then(({default: fetch}) => fetch(...args));

const results = {
  db: { success: null, error: null },
  anthropic: { success: null, error: null },
  stripe: { success: null, error: null },
};

async function testDatabase() {
  const client = new Client({ connectionString: process.env.DATABASE_URL });
  try {
    await client.connect();
    // simple query to ensure the connection works
    await client.query('SELECT 1');
    results.db.success = true;
  } catch (e) {
    results.db.success = false;
    results.db.error = e.message;
  } finally {
    await client.end();
  }
}

async function testAnthropic() {
  const url = 'https://api.anthropic.com/v1/models';
  const key = process.env.ANTHROPIC_API_KEY;
  try {
    const res = await fetch(url, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': key,
      },
    });
    if (!res.ok) throw new Error(`Status ${res.status}`);
    await res.json();
    results.anthropic.success = true;
  } catch (e) {
    results.anthropic.success = false;
    results.anthropic.error = e.message;
  }
}

async function testStripe() {
  const stripe = stripeLib(process.env.STRIPE_SECRET_KEY, { apiVersion: '2023-10-16' });
  try {
    await stripe.customers.retrieve('nonexistent-customer-123', { stripeAccount: undefined });
    // If retrieve succeeds without throwing, the key works.
    results.stripe.success = true;
  } catch (e) {
    // Stripe throws if the account doesn't exist but the key is valid.
    if (e.type === 'StripeInvalidRequestError' && e.code === 'resource_missing') {
      results.stripe.success = true;
    } else {
      results.stripe.success = false;
      results.stripe.error = e.message;
    }
  }
}

(async () => {
  console.log('Running credential checks…');
  await Promise.all([testDatabase(), testAnthropic(), testStripe()]);

  console.log('\n=== Results ===');
  for (const [k, v] of Object.entries(results)) {
    if (v.success) {
      console.log(`✅ ${k}: OK`);
    } else {
      console.log(`❌ ${k}: Failed (${v.error})`);
    }
  }
})();

