const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { validationResult, body, query } = require('express-validator');
const morgan = require('morgan');

const app = express();

/* ---------- 1. Middleware ----------
├─ helmet   → XSS / click‑jacking header protection
├─ cors     → Guard the API against open CORS
├─ rateLimiter → Throttle bad actors
├─ morgan  → Structured logging for CI & ops
├─ express.json()/urlencoded → Cookie / body parsing
*/
app.use(helmet());

app.use(
  cors({
    // Restrict to specific origins (change as needed)
    origin: process.env.CORS_ORIGIN || '*',
    optionsSuccessStatus: 200,
  })
);

// Basic request logging in morgan’s combined format
app.use(morgan('combined'));

// Rate limiting – 100 requests / 10 min per IP
app.use(
  rateLimit({
    windowMs: 10 * 60 * 1000,
    max: 100,
    handler: (req, res) => {
      res.status(429).json({
        error: 'Too many requests, please try again later.',
      });
    },
  })
);

