  // Example of guarding the route even if it becomes async
  async (req, res, next) => {
    try {
      res.json({
        status: 'ok',
        timestamp: new Date().toISOString(),
      });
    } catch (err) {
      next(err); // forwarded to global error handler
    }
  }
);

app.get(
  '/users',
  // In case we decide to filter users via query string
  body('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('limit must be an integer between 1 and 100')
    .toInt(),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      // Return first validation error for brevity
