);

/* ---------- 3. 404 Handler ----------
 *
 * All unmatched paths should return JSON instead of plain text.
 */
app.use((req, res, next) => {
  res.status(404).json({ error: `Endpoint ${req.originalUrl} not found.` });
});

/* ---------- 4. Global Error Handler ----------
 *
 * Catch both sync & async errors in a single place.
 * Do NOT leak stack traces in production.
 */
app.use((err, req, res, next) => {
  // Log the error – replace with a structured logger in prod
  console.error(err.stack);

  const statusCode = err.statusCode || 500;
  const response = {
    error: err.message || 'Internal Server Error',
  };

  // In prod, hide stack trace
  if (process.env.NODE_ENV !== 'production') {
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

/* ---------- 5. Server bootstrap ----------
 *
 * Grab the port from environment – defaults to 3000 for dev.
 */
const PORT = parseInt(process.env.PORT || '3000', 10);

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown (handles `SIGINT`/`SIGTERM`)
function gracefulShutdown() {
  console.log('Shutting down gracefully...');
  server.close(() => {
    console.log('Closed out remaining connections.');
    process.exit(0);
  });
}

process.on('SIGINT', gracefulShutdown);
process.on('SIGTERM', gracefulShutdown);

module.exports = app;
