"use strict";

require("dotenv").config();          // Load .env vars
const express = require("express");
const helmet = require("helmet");
const rateLimit = require("express-rate-limit");
const cors = require("cors");
const { query, validationResult } = require("express-validator");

const app = express();

/* ------------------------------------------------------------------
 * 1️⃣ Global Middleware
 * ------------------------------------------------------------------ */
app.use(helmet());                   // Secure headers
app.use(express.json({ limit: "1kb" })); // Small body limit

/* 2️⃣ Rate limiter (15 min window, 100 requests per IP) */
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: "Too many requests, try again later." }
});
app.use(limiter);

/* 3️⃣ CORS – allow only whitelisted origins.
   (Set WHITELIST_ORIGINS in .env if you have a list) */
const WHITELIST_ORIGINS = process.env.WHITELIST_ORIGINS
  ? process.env.WHITELIST_ORIGINS.split(",")
  : [];
app.use(
  cors({
    origin: function (origin, callback) {
      // Allow requests with no CORS header (e.g. server <-> server)
      if (!origin) return callback(null, true);

      if (WHITELIST_ORIGINS.includes(origin)) {
        return callback(null, true);
      } else {
        return callback(new Error("Not allowed by CORS"));
      }
    },
    methods: ["GET", "POST", "OPTIONS"],
    preflightContinue: false,
    optionsSuccessStatus: 204
  })
);

/* 4️⃣ Routes (example: health check) */
app.get("/health", (req, res) => {
  res.locals.requestId = req.id ?? Date.now(); // If you have request‑id middlware
