    } catch (err) {
      /* Forward unexpected errors to central handler */
      next(err);
    }
  }
);

/* ------------------------------------------------------------------
 * 6️⃣ Central Error Handler (must be last)
 * ------------------------------------------------------------------ */
app.use((err, req, res, next) => {
  // Log err – in prod you’d want a structured logger
  console.error(err);

  // Send user‑friendly, non‑sensitive message
  res.status(500).json({ error: "Internal Server Error" });
});

/* ------------------------------------------------------------------
 * 7️⃣ Start the server
 * ------------------------------------------------------------------ */
