// app.js
// -------------------------------------------
// Security‑focused Express skeleton
// -------------------------------------------

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const createError = require('http-errors');
require('express-async-errors');   // automatically forward async errors to the error handler

const app = express();

// ---- 1. Security middlewares -------------------------------------------------

// 1️⃣ Headers
app.use(helmet()); // Good defaults: XSS, click‑jacking, MIME sniffing

// 2️⃣ Logging
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// 3️⃣ CORS (customise whitelist if needed)
//    `origin: '*'` works for public APIs, but real projects may need restriction.
app.use(cors());

// 4️⃣ Rate limiting (basic, can be tweaked)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 200,                 // limit each IP to 200 requests per windowMs
  standardHeaders: true,    // return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false,
});
app.use(limiter);

// ---- 2. Body parsing ---------------------------------------------------------

app.use(express.json());   // In case you add POST/PUT endpoints in later iterations

// ---- 3. Routes ---------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // 👉 Future security note: Make‑sure the email field is intentionally exposed.
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ---- 4. 404 handling -----------------------------------------------------------

app.use((req, _res, next) => {
  next(createError.NotFound());
});

// ---- 5. Global error handler --------------------------------------------------

app.use((err, _req, res, _next) => {
  // Internal server errors should not leak stack traces
  const status = err.status || err.statusCode || 500;
  // Keep the response compact and informative
  const body = {
    status: 'error',
    code: status,
  };
  // Do not expose internal details in production
  if (status >= 500) {
    body.message = 'Internal Server Error';
  } else {
    body.message = err.message;
  }

  res.status(status).json(body);
});

// ---- 6. Server startup --------------------------------------------------------

const PORT = process.env.PORT ?? 3000;
app.listen(PORT, () => {
  console.log(`🚀 Server running on http://localhost:${PORT}`);
});

module.exports = app;
```

