// ==================================================
// The code below is a heavily annotated and rewritten
// version of the original file.  The original project
// was intentionally minimal, but in a production
// environment you should add the following security
// and robustness features:
//   1. Parse JSON request bodies safely.
//   2. Use Helmet to set common HTTP headers for
//      basic protection (XSS, content‑type‑nosniff,
//      etc.).
//   3. Add a generic error‑handling middleware.  This
//      prevents stack traces from leaking to clients.
//   4. If the routes ever accept user input (query,
//      path or body parameters) validate them using a
//      schema library such as Joi or celebrate.
//   5. When exposing databases or any data, sanitize
//      any identifiers before using them in database
//      statements – this keeps against injection.
//   6. Enable HTTPS, set strict‑transport‑security if
//      possible and turn on CORS with a whitelist.
//
// For demonstration purposes below we keep the original
// behaviour but add the middleware and structure the file
// to allow easy extension.
// ==================================================

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const app = express();

// ------------------------------------------------------------------
// Middleware
// ------------------------------------------------------------------
// Parse JSON bodies (express 4.16+ includes this).  We set a
// reasonable size limit; if your API consumes large payloads you
// can adjust.
app.use(express.json({ limit: '1mb' }));

// Use Helmet to set various HTTP headers – protects against
// several well‑known web vulnerabilities.
app.use(helmet());

// Rate limit all requests – this reduces the risk of
// brute‑force or DoS attacks.
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per window
  message: { error: 'Too many requests, please try again later.' }
});
app.use(limiter);

// Enable CORS only for a known origin list; this prevents
// cross‑site request forgery from arbitrary domains.
app.use(
  cors({
    origin: ['http://localhost:3000', 'https://mytrustedapp.com'],
    optionsSuccessStatus: 200
  })
);

// ------------------------------------------------------------------
// Routes
// ------------------------------------------------------------------
// Health endpoint – a simple liveness check.
app.get('/health', (req, res, next) => {
  try {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  } catch (err) {
    next(err);
  }
});

// Sample users endpoint – in a real application you would
// fetch this data from a database.
app.get('/users', (req, res, next) => {
  try {
    // TODO: If this route ever requires query params, validate
    // them before using them to prevent injection.
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ]);
  } catch (err) {
    next(err);
  }
});

// ------------------------------------------------------------------
// Error handling
// ------------------------------------------------------------------
// Centralised error‑handling middleware.  It logs the error to
// console (or a logging service) and returns a generic message.
app.use((err, req, res, next) => {
  console.error(err.stack); // replace with proper logger in production
  res.status(500).json({ error: 'Internal Server Error' });
});

// ------------------------------------------------------------------
// Server startup
// ------------------------------------------------------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

#!/usr/bin/env node
"use strict";

/*
 * verify_credentials.js
 * ---------------------
 * A quick one‑off helper that will
 * 1. Read the test environment file (.env.test)
 * 2. Attempt to connect to the database URL
 * 3. Send a minimal request to each API service
 *    (AWS, Anthropic, Stripe, Logfire)
 *
 * It prints a summary of successes / failures.
 *
 * Usage:  node test/verify_credentials.js
 *
 * Dependencies (install first):
 *   npm i pg aws-sdk@^3 anthropic stripe node-fetch
 */

const fs = require('fs');
const path = require('path');
const { Client } = require('pg');
const { S3Client, ListBucketsCommand } = require('@aws-sdk/client-s3');
const { Anthropic } = require('anthropic');
const Stripe = require('stripe');
const fetch = require('node-fetch');

// Load .env.test (non‑standard env file name).  If it
// cannot be found we bail out with an error.
const envPath = path.resolve(process.cwd(), '.env.test');
if (!fs.existsSync(envPath)) {
  console.error('❌  .env.test not found in the project root.');
  process.exit(1);
}
require('dotenv').config({ path: envPath });

const results = [];

// 1️⃣  PostgreSQL – simple "SELECT 1"
async function testDb() {
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    return { id: 'db', ok: false, err: 'DATABASE_URL not set' };
  }
  const client = new Client({ connectionString: dbUrl });
  try {
    await client.connect();
    await client.query('SELECT 1');
    return { id: 'db', ok: true };
  } catch (err) {
    return { id: 'db', ok: false, err: err.message };
  } finally {
    await client.end();
  }
}

// 2️⃣  AWS – list S3 buckets (requires credentials)
async function testAws() {
  const accessKey = process.env.AWS_ACCESS_KEY_ID;
  const secretKey = process.env.AWS_SECRET_ACCESS_KEY;
  if (!accessKey || !secretKey) {
    return { id: 'aws', ok: false, err: 'AWS credentials missing' };
  }
  try {
    const s3 = new S3Client({
      credentials: { accessKeyId: accessKey, secretAccessKey: secretKey }
    });
    const resp = await s3.send(new ListBucketsCommand({}));
    // If we get a bucket list, we assume the credentials are good
    return { id: 'aws', ok: true, buckets: resp.Buckets?.length || 0 };
  } catch (err) {
    return { id: 'aws', ok: false, err: err.message };
  }
}

// 3️⃣  Anthropic – list models (requires API key)
async function testAnthropic() {
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) {
    return { id: 'anthropic', ok: false, err: 'ANTHROPIC_API_KEY missing' };
  }
  try {
    const client = new Anthropic({ apiKey: key });
    const models = await client.listModels();
    return { id: 'anthropic', ok: true, models: models.length };
  } catch (err) {
    return { id: 'anthropic', ok: false, err: err.message };
  }
}

// 4️⃣  Stripe – retrieve balance (requires secret key)
async function testStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) {
    return { id: 'stripe', ok: false, err: 'STRIPE_SECRET_KEY missing' };
  }
  try {
    const stripe = Stripe(key, { apiVersion: '2024-04-09' });
    const balance = await stripe.balance.retrieve();
    return { id: 'stripe', ok: true, balance: balance.available?.[0]?.amount || 0 };
  } catch (err) {
    return { id: 'stripe', ok: false, err: err.message };
  }
}

// 5️⃣  Logfire – simple POST test (requires token)
async function testLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) {
    return { id: 'logfire', ok: false, err: 'LOGFIRE_TOKEN missing' };
  }
  try {
    // Logfire exposes its HTTP API at https://api.logfire.com/v1/events
    const resp = await fetch('https://api.logfire.com/v1/events', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${token}`
      },
      body: JSON.stringify({ message: 'healthcheck', level: 'info' })
    });
    if (!resp.ok) throw new Error(`status ${resp.status}`);
    return { id: 'logfire', ok: true, status: resp.status };
  } catch (err) {
    return { id: 'logfire', ok: false, err: err.message };
  }
}

async function runAll() {
  const funcs = [testDb, testAws, testAnthropic, testStripe, testLogfire];
  const promises = funcs.map(fn => fn());
  const out = await Promise.all(promises);

  console.log('\n✅  Credential Verification Summary');
  out.forEach(r => {
    if (r.ok) {
      console.log(`  ✔  ${r.id}: OK`);
      if (r.buckets !== undefined) console.log(`    • Buckets: ${r.buckets}`);
      if (r.models !== undefined) console.log(`    • Models: ${r.models}`);
      if (r.balance !== undefined) console.log(`    • Stripe balance: ${r.balance}`);
      if (r.status !== undefined) console.log(`    • Logfire response: ${r.status}`);
    } else {
      console.error(`  ✘  ${r.id}: FAILED – ${r.err}`);
    }
  });

  const failures = out.filter(r => !r.ok);
  process.exit(failures.length ? 1 : 0);
}

runAll();

